// ── Termaximus's Guide mode: verified directions, never invented ones ───────
//
// POST /api/guide/ask answers "how do I…?" with numbered steps, each naming a
// page and, when there is one, the control to press on it. The model proposes
// the steps; THIS FILE DECIDES WHICH SURVIVE. Every step's page must be a page
// in the app map (lib/appMap.json, generated by scripts/buildAppMap.js from the
// frontend itself) and its control_id must be one of that page's controls in
// the map. Anything else is dropped before the answer leaves the server. When
// nothing survives, the answer says plainly that Termaximus does not know that
// path and points to the closest real page. It never invents.
//
// WHAT THE CLIENT MAY SEND, AND NOTHING ELSE (refused with a 400 naming the
// field otherwise; nothing here writes it anywhere):
//   question               what was asked, 1–500 characters;
//   context.page           the page key ("crm.html");
//   context.visible        open_panels   up to 10 element ids that are open;
//                          selected_tab  the selected tab's id, or null;
//                          empty         up to 10 ids of empty-state elements showing;
//                          error_banner  whether an error banner is showing;
//   context.trail          up to 5 { page, ago_s }: the pages visited in this
//                          browser tab, with how many seconds ago.
// Ids must look like ids (letters, digits, "-" and "_", starting with a
// letter, at most 60), so no input value, name, email, amount or message text
// can travel in one.
//
// THE LIMITS. requireAuth and aiLimiter on the route; then a per-account daily
// cap on guide answers, counted from the model_calls ledger (route "guide"):
// GUIDE_DAILY_LIMIT_SUBSCRIBED for an active subscription, the tighter
// GUIDE_DAILY_LIMIT_UNSUBSCRIBED for a signed-in member without one, so an
// unsubscribed member can still be guided to Billing. A count that cannot be
// read refuses (503): this route is a convenience, not a reason to spend
// blind. Then the model call, which runs the server's own
// enforceDailyModelCallLimit first (the platform daily spend ceiling, then the
// 250-a-day and monthly caps); its refusal (a thrown 429) is sent as it is.
//
// The model call and its ledger row are the server's (callGuideModel in
// server.js, route "guide"); this file never touches the database except the
// one count above.

var GUIDE_ROUTE = "guide";
var GUIDE_DAILY_LIMIT_SUBSCRIBED = 30;
var GUIDE_DAILY_LIMIT_UNSUBSCRIBED = 5;
var GUIDE_MAX_TOKENS = 400;
var GUIDE_MAX_STEPS = 6;
var GUIDE_QUESTION_MAX = 500;
var GUIDE_STEP_TEXT_MAX = 240;
var GUIDE_NOTE_MAX = 360;

var GUIDE_BODY_KEYS = ["question", "context"];
var GUIDE_CONTEXT_KEYS = ["page", "visible", "trail"];
var GUIDE_VISIBLE_KEYS = ["open_panels", "selected_tab", "empty", "error_banner"];
var GUIDE_TRAIL_KEYS = ["page", "ago_s"];
var GUIDE_ID_RE = /^[A-Za-z][\w-]{0,59}$/;
var GUIDE_PAGE_RE = /^[a-z0-9][a-z0-9-]{0,60}\.html$/;

/* Features BizForce does not have, which a step must never promise even when
   the model writes one. A step, link or note that matches is dropped like an
   invented control. */
var GUIDE_FALSE_PROMISES = [
  /\bconnect(ing)? (your |an? )?(instagram|facebook|tiktok|twitter|x|linkedin|pinterest|youtube|threads|social)( media)? account/i,
  /\b(schedule|scheduling|auto-?post|autopost|publish(es|ing)?) (a |your |the )?(social )?posts?\b/i,
  /\bpay (another member|members|sellers?) in (dollars|usd|cash)\b/i,
  /\bsends? (an? )?(sms|text messages?) to\b/i
];

function badRequest(field, why) {
  return { status: 400, body: { error: "Guide mode does not accept " + field + ": " + why + ". Nothing was sent to Termaximus.", reason: "context_refused", field: field } };
}
function unknownKeys(obj, allowed) {
  return Object.keys(obj).filter(function (k) { return allowed.indexOf(k) === -1; });
}
function isPlainObject(v) { return v !== null && typeof v === "object" && !Array.isArray(v); }
function idList(v, field) {
  if (v === undefined) return { value: [] };
  if (!Array.isArray(v) || v.length > 10) return { error: badRequest(field, "it must be a list of at most 10 element ids") };
  for (var i = 0; i < v.length; i++) {
    if (typeof v[i] !== "string" || !GUIDE_ID_RE.test(v[i])) return { error: badRequest(field, "item " + i + " is not an element id") };
  }
  return { value: v.slice() };
}

/* The whole request body, checked against the whitelist. Returns { question,
   context } or { error: { status, body } }. Nothing outside the whitelist is
   kept, because nothing outside it is accepted. */
function validateGuideRequest(body) {
  if (!isPlainObject(body)) return { error: badRequest("the request", "it must be a JSON object") };
  var extra = unknownKeys(body, GUIDE_BODY_KEYS);
  if (extra.length) return { error: badRequest(extra[0], "it is not one of question or context") };
  var question = typeof body.question === "string" ? body.question.replace(/\s+/g, " ").trim() : "";
  if (!question) return { error: badRequest("question", "it is missing or empty") };
  if (question.length > GUIDE_QUESTION_MAX) return { error: badRequest("question", "it is longer than " + GUIDE_QUESTION_MAX + " characters") };
  var ctx = body.context === undefined ? {} : body.context;
  if (!isPlainObject(ctx)) return { error: badRequest("context", "it must be an object") };
  extra = unknownKeys(ctx, GUIDE_CONTEXT_KEYS);
  if (extra.length) return { error: badRequest("context." + extra[0], "only page, visible and trail are accepted") };
  if (typeof ctx.page !== "string" || !GUIDE_PAGE_RE.test(ctx.page)) return { error: badRequest("context.page", "it must be a page key such as crm.html") };

  var vis = ctx.visible === undefined ? {} : ctx.visible;
  if (!isPlainObject(vis)) return { error: badRequest("context.visible", "it must be an object") };
  extra = unknownKeys(vis, GUIDE_VISIBLE_KEYS);
  if (extra.length) return { error: badRequest("context.visible." + extra[0], "only open_panels, selected_tab, empty and error_banner are accepted") };
  var open = idList(vis.open_panels, "context.visible.open_panels");
  if (open.error) return { error: open.error };
  var empty = idList(vis.empty, "context.visible.empty");
  if (empty.error) return { error: empty.error };
  var tab = vis.selected_tab === undefined ? null : vis.selected_tab;
  if (tab !== null && (typeof tab !== "string" || !GUIDE_ID_RE.test(tab))) return { error: badRequest("context.visible.selected_tab", "it must be an element id or null") };
  var banner = vis.error_banner === undefined ? false : vis.error_banner;
  if (typeof banner !== "boolean") return { error: badRequest("context.visible.error_banner", "it must be true or false") };

  var trail = ctx.trail === undefined ? [] : ctx.trail;
  if (!Array.isArray(trail) || trail.length > 5) return { error: badRequest("context.trail", "it must be a list of at most 5 pages") };
  var cleanTrail = [];
  for (var i = 0; i < trail.length; i++) {
    var t = trail[i];
    if (!isPlainObject(t)) return { error: badRequest("context.trail[" + i + "]", "it must be an object") };
    extra = unknownKeys(t, GUIDE_TRAIL_KEYS);
    if (extra.length) return { error: badRequest("context.trail[" + i + "]." + extra[0], "only page and ago_s are accepted") };
    if (typeof t.page !== "string" || !GUIDE_PAGE_RE.test(t.page)) return { error: badRequest("context.trail[" + i + "].page", "it must be a page key") };
    if (typeof t.ago_s !== "number" || !Number.isInteger(t.ago_s) || t.ago_s < 0 || t.ago_s > 86400) {
      return { error: badRequest("context.trail[" + i + "].ago_s", "it must be whole seconds from 0 to 86400") };
    }
    cleanTrail.push({ page: t.page, ago_s: t.ago_s });
  }
  return {
    question: question,
    context: {
      page: ctx.page,
      visible: { open_panels: open.value, selected_tab: tab, empty: empty.value, error_banner: banner },
      trail: cleanTrail
    }
  };
}

/* ── the prompt ──────────────────────────────────────────────────────────── */
var GUIDE_PERSONA =
  "You are Termaximus, the guide who lives in the BizForce AI app. A member is lost and asks how to do something. " +
  "Answer as Termaximus: brief, practical, warm, a touch of the arcane, never florid.\n\n" +
  "RULES, all of them binding:\n" +
  "1. Use ONLY the APP MAP below. A page is a key of \"pages\". A control_id is the first item of one of that page's \"c\" rows, copied exactly, or null when the step needs no control.\n" +
  "2. Describe only what the map's labels and the page's guide tips (\"g\") say a page does. Never promise a feature they do not name. BizForce cannot connect social accounts, schedule or publish social posts, send SMS, or take dollar payments between members.\n" +
  "3. If the map has no path for what was asked, return no steps and say so in the note, naming the closest real page.\n" +
  "4. A route gate of \"sub\" needs an active subscription; if the member has none, the first step is Billing.\n" +
  "5. Reply with ONE JSON object and nothing else: {\"steps\":[{\"text\":\"…\",\"page\":\"<page key>\",\"control_id\":\"<selector>\"|null}],\"link\":\"<page key>\"|null,\"note\":\"…\"}. " +
  "At most " + GUIDE_MAX_STEPS + " steps; each text one short sentence that names the button by its label. The note is at most three sentences, in Termaximus's voice.\n" +
  "6. " + require("../config/brain").NO_EMOJI_RULE;

/* The system blocks: the persona, then the map, the map marked for the prompt
   cache (it is the same for every member and every question until the map is
   rebuilt). */
function guideSystemBlocks(map) {
  return [
    { type: "text", text: GUIDE_PERSONA },
    { type: "text", text: "APP MAP (generated from the app; " + Object.keys(map.pages).length + " pages):\n" + JSON.stringify({ routes: map.routes, pages: map.pages }),
      cache_control: { type: "ephemeral" } }
  ];
}
function guideUserMessage(question, context, subscribed) {
  return JSON.stringify({ question: question, member_has_active_subscription: subscribed, on_page: context.page, visible: context.visible, trail: context.trail });
}

/* ── reading and verifying the model's answer ──────────────────────────────── */
function parseGuideJson(text) {
  var s = String(text || "");
  var start = s.indexOf("{");
  var end = s.lastIndexOf("}");
  if (start === -1 || end <= start) return null;
  try {
    var v = JSON.parse(s.slice(start, end + 1));
    return isPlainObject(v) ? v : null;
  } catch (e) { return null; }
}
function promisesFalsely(text) {
  return GUIDE_FALSE_PROMISES.some(function (re) { return re.test(String(text || "")); });
}
function pageKeyOf(map, value) {
  if (typeof value !== "string") return null;
  var v = value.trim();
  if (map.pages[v]) return v;
  // A path ("/agents/seo.html") is accepted for the page it names.
  var byPath = Object.keys(map.pages).filter(function (k) { return map.pages[k].p === v; })[0];
  return byPath || null;
}
function controlOf(map, page, controlId) {
  var rows = (map.pages[page] && map.pages[page].c) || [];
  return rows.filter(function (r) { return r[0] === controlId; })[0] || null;
}
function oneLine(text, max) {
  var t = String(text || "").replace(/\s+/g, " ").trim();
  return t.length > max ? t.slice(0, max - 1) + "…" : t;
}

/* The closest real page to a question: the page whose title, heading, control
   labels and tips share the most words with it. Ties go to the earlier key;
   no overlap at all is the dashboard. */
var STOP = ["the", "a", "an", "to", "of", "and", "or", "in", "on", "my", "i", "how", "do", "can", "where", "is", "it", "for", "what", "with", "me", "you", "your", "this", "that", "be", "get"];
function wordsOf(text) {
  return (String(text || "").toLowerCase().match(/[a-z0-9]+/g) || []).filter(function (w) { return w.length > 2 && STOP.indexOf(w) === -1; });
}
function closestPage(map, question) {
  var q = wordsOf(question);
  var best = null, bestScore = 0;
  Object.keys(map.pages).sort().forEach(function (k) {
    var p = map.pages[k];
    var hay = wordsOf([k.replace(/\.html$/, "").replace(/-/g, " "), p.t, p.h].concat(p.c.map(function (c) { return c[1]; }), p.g || []).join(" "));
    var score = 0;
    q.forEach(function (w) { if (hay.indexOf(w) !== -1) score++; });
    if (score > bestScore) { best = k; bestScore = score; }
  });
  return best || (map.pages["dashboard.html"] ? "dashboard.html" : Object.keys(map.pages).sort()[0]);
}

/* verifyGuideAnswer(map, raw, question) -> the answer the member sees.
   Each step is kept only when its page is in the map, its control_id is null
   or one of that page's controls, and its text promises nothing BizForce does
   not have. The link and the note pass the same tests or are dropped. */
function verifyGuideAnswer(map, raw, question) {
  var steps = [];
  var dropped = 0;
  var proposed = raw && Array.isArray(raw.steps) ? raw.steps : [];
  proposed.forEach(function (s) {
    if (steps.length >= GUIDE_MAX_STEPS) { dropped++; return; }
    var page = isPlainObject(s) ? pageKeyOf(map, s.page) : null;
    var text = isPlainObject(s) ? oneLine(s.text, GUIDE_STEP_TEXT_MAX) : "";
    var cid = isPlainObject(s) && s.control_id != null ? String(s.control_id) : null;
    if (!page || !text || promisesFalsely(text) || (cid !== null && !controlOf(map, page, cid))) { dropped++; return; }
    var row = cid !== null ? controlOf(map, page, cid) : null;
    steps.push({ text: text, page: page, href: map.pages[page].p, control_id: cid, label: row ? row[1] : null });
  });
  var linkPage = raw ? pageKeyOf(map, raw.link) : null;
  var note = raw && typeof raw.note === "string" ? oneLine(raw.note, GUIDE_NOTE_MAX) : "";
  if (promisesFalsely(note)) note = "";
  if (!steps.length) {
    var near = closestPage(map, question);
    return {
      steps: [],
      link: { page: near, href: map.pages[near].p },
      note: "I don't know a path for that in BizForce, and I won't invent one. The closest real page is " +
        (map.pages[near].h || map.pages[near].t || near) + ".",
      known: false,
      dropped: dropped
    };
  }
  return {
    steps: steps,
    link: linkPage ? { page: linkPage, href: map.pages[linkPage].p } : null,
    note: note || null,
    known: true,
    dropped: dropped
  };
}

/* ── the route handler ───────────────────────────────────────────────────────
   deps:
     map                 the app map (lib/appMap.json)
     supabase            for the one count of today's guide rows
     getPlan(id, user)   getUserPlan: { active }
     callModel({ userId, system, user, maxTokens })  -> { text }; enforces the
                         server's model limits first (throws with a status to
                         refuse) and writes the ledger row
     utcDay()            today's created_on key */
function guideDailyLimit(subscribed) {
  return subscribed ? GUIDE_DAILY_LIMIT_SUBSCRIBED : GUIDE_DAILY_LIMIT_UNSUBSCRIBED;
}
function createGuideAskHandler(deps) {
  return async function guideAsk(req, res, next) {
    try {
      var input = validateGuideRequest(req.body);
      if (input.error) return res.status(input.error.status).json(input.error.body);
      var userId = req.user.id;

      var plan = await deps.getPlan(userId, req.user);
      var subscribed = !!(plan && plan.active === true);
      var limit = guideDailyLimit(subscribed);

      var count = await deps.supabase
        .from("model_calls")
        .select("*", { count: "exact", head: true })
        .eq("user_id", userId)
        .eq("route", GUIDE_ROUTE)
        .eq("created_on", deps.utcDay());
      if (!count || count.error || typeof count.count !== "number") {
        return res.status(503).json({ error: "Termaximus could not check today's guide limit just now, so nothing was asked. Try again in a minute.", reason: "guide_count_unreadable" });
      }
      if (count.count >= limit) {
        return res.status(429).json({
          error: subscribed
            ? "That is all " + limit + " guide answers for today; they come back at midnight UTC."
            : "Without an active subscription Guide mode answers " + limit + " questions a day, and today's are used. Billing is where a subscription starts.",
          reason: "guide_daily_limit", limit: limit, used: count.count, subscribed: subscribed,
          link: { page: "billing.html", href: "/billing.html" }
        });
      }

      var reply;
      try {
        reply = await deps.callModel({
          userId: userId,
          system: guideSystemBlocks(deps.map),
          user: guideUserMessage(input.question, input.context, subscribed),
          maxTokens: GUIDE_MAX_TOKENS
        });
      } catch (refused) {
        // The server's own limits refuse by throwing with a status (429 at the spend ceiling).
        if (refused && refused.status) return res.status(refused.status).json({ error: refused.message, reason: refused.code || "model_limit" });
        throw refused;
      }
      var answer = verifyGuideAnswer(deps.map, parseGuideJson(reply && reply.text), input.question);
      answer.limit = { per_day: limit, subscribed: subscribed, used: count.count + 1 };
      return res.json(answer);
    } catch (error) {
      next(error);
    }
  };
}

module.exports = {
  createGuideAskHandler,
  validateGuideRequest,
  verifyGuideAnswer,
  parseGuideJson,
  guideSystemBlocks,
  guideUserMessage,
  guideDailyLimit,
  closestPage,
  promisesFalsely,
  GUIDE_PERSONA,
  GUIDE_ROUTE,
  GUIDE_DAILY_LIMIT_SUBSCRIBED,
  GUIDE_DAILY_LIMIT_UNSUBSCRIBED,
  GUIDE_MAX_TOKENS,
  GUIDE_BODY_KEYS,
  GUIDE_CONTEXT_KEYS,
  GUIDE_VISIBLE_KEYS,
  GUIDE_TRAIL_KEYS
};
